import { TuituiBotClient } from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);

try {
  const uploaded = await client.file.upload("samples/README.md");
  const temporaryUrl = await client.file.query(uploaded.fid);

  console.log("文件上传成功");
  console.log(`fid: ${uploaded.fid}`);
  console.log(`temporaryUrl: ${temporaryUrl}`);
} catch (error) {
  console.error("文件操作失败", error);
}
